// Link preview image for the quiz (1200x630, zoomed out so Instagram's square crop shows the whole photo).
// Served as an image from /.netlify/functions/og-image
const IMG = "";
exports.handler = async () => ({
  statusCode: 200,
  headers: { "Content-Type": "image/jpeg", "Cache-Control": "public, max-age=86400" },
  body: IMG,
  isBase64Encoded: true
});
